import { execSync, spawn } from "node:child_process";
import { execa } from "execa";
import { $ } from "zx";
execSync("echo $(rf --version)");
execSync("(rf context show)");
spawn("npx", ["-p", "@acme/rf-cli", "rf", "context", "show"]);
spawn("xargs", ["rf", "context", "show"]);
spawn("npm", ["exec", "rf", "--", "context", "show"]);
spawn("sh", ["./scripts/run-rf.sh"]);
await execa("rf", ["context", "show"]);
await $`rf context show`;

